function sizeSignatureCanvas(){const ratio=window.devicePixelRatio||1,w=Math.min(700,Math.max(280,window.innerWidth-50)),h=220;sigCanvas.style.width=w+'px';sigCanvas.style.height=h+'px';sigCanvas.width=w*ratio;sigCanvas.height=h*ratio;sigCtx.setTransform(ratio,0,0,ratio,0,0);sigCtx.lineWidth=2.5;sigCtx.lineCap='round';sigCtx.strokeStyle='#111827';sigCtx.fillStyle='#fff';sigCtx.fillRect(0,0,w,h);if(state.signatureData){const im=new Image();im.onload=()=>sigCtx.drawImage(im,0,0,w,h);im.src=state.signatureData}}
