sigCanvas.addEventListener('pointerdown',sigStart);sigCanvas.addEventListener('pointermove',sigMove);window.addEventListener('pointerup',sigEnd);sigCanvas.addEventListener('touchstart',sigStart,{passive:false});sigCanvas.addEventListener('touchmove',sigMove,{passive:false});sigCanvas.addEventListener('touchend',sigEnd);
$('signBtn').onclick=()=>{header();sigDialog.showModal();setTimeout(sizeSignatureCanvas,30)};$('clearSignature').onclick=()=>{state.signatureData='';state.signatureSignedAt='';sizeSignatureCanvas()};$('saveSignature').onclick=async()=>{state.signatureData=sigCanvas.toDataURL('image/png');state.signatureSignedAt=new Date().toISOString();await save();sigDialog.close();toast('Signature saved / 簽名已儲存')};$('deleteSignature').onclick=async()=>{if(!confirm('Delete signature? / 刪除簽名？'))return;state.signatureData='';state.signatureSignedAt='';await save();sizeSignatureCanvas();toast('Signature deleted / 簽名已刪除')};
