function authMsg(text,type='info'){const el=$('authMessage');el.textContent=text;el.className='auth-message '+type}
function setAuthMode(mode){authMode=mode;const signup=mode==='signup';$('showSignIn').classList.toggle('active',!signup);$('showSignUp').classList.toggle('active',signup);$('authCompanyWrap').hidden=!signup;$('authSubmit').textContent=signup?'Create Account / 建立帳戶':'Sign In / 登入';$('authPassword').autocomplete=signup?'new-password':'current-password';authMsg('')}
