function writeOfflineLicence(userId,row){const validUntil=row.offline_license_until||row.current_period_end;if(!validUntil)return;localStorage.setItem(offlineLicenceKey(userId),JSON.stringify({status:row.status,plan:row.plan||'professional',validUntil,email:row.email,checkedAt:new Date().toISOString()}))}
