async function submitAuth(){const email=$('authEmail').value.trim().toLowerCase(),password=$('authPassword').value,company=$('authCompany').value.trim();if(!email||!password)return authMsg('Enter your email and password.','error');if(password.length<12)return authMsg('Password must contain at least 12 characters.','error');$('authSubmit').disabled=true;authMsg(authMode==='signup'?'Creating account…':'Signing in…');try{if(authMode==='signup'){const {data,error}=await supabaseClient.auth.signUp({email,password,options:{emailRedirectTo:'https://kawaikay.github.io/sitesafe-inspector/',data:{company}}});if(error)throw error;if(data.session){currentAuthUser=data.user;await checkLicence()}else authMsg('Account created. Check your email and confirm the account, then return and sign in.','success')}else{const {data,error}=await supabaseClient.auth.signInWithPassword({email,password});if(error)throw error;currentAuthUser=data.user;await checkLicence()}}catch(err){authMsg(err.message||String(err),'error')}finally{$('authSubmit').disabled=false}}
async function resetPassword(){const email=$('authEmail').value.trim().toLowerCase();if(!email)return authMsg('Enter your email first.','error');const {error}=await supabaseClient.auth.resetPasswordForEmail(email,{redirectTo:'https://kawaikay.github.io/sitesafe-inspector/'});authMsg(error?error.message:'Password reset email sent.',error?'error':'success')}
async function signOutCommercial(){if(currentAuthUser)localStorage.removeItem(offlineLicenceKey(currentAuthUser.id));await supabaseClient.auth.signOut();currentAuthUser=null;currentLicence=null;$('accountDialog')?.close();setAuthMode('signin');showAuth()}
async function initCommercialAccess(){const startup=$('authStartup');if(startup)startup.textContent='Connecting to Supabase…';if(!window.supabase){document.body.innerHTML='<main class="fatal-config"><h1>SiteSafe Inspector</h1><p>Authentication service could not load. Connect to the internet and reload once.</p></main>';return}if(startup)startup.textContent='Account service ready.';supabaseClient=window.supabase.createClient(SUPABASE_URL,SUPABASE_PUBLISHABLE_KEY,{auth:{persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});$('showSignIn').onclick=()=>setAuthMode('signin');$('showSignUp').onclick=()=>setAuthMode('signup');$('authSubmit').onclick=submitAuth;$('forgotPassword').onclick=resetPassword;$('refreshLicence').onclick=()=>checkLicence();$('licenseSignOut').onclick=signOutCommercial;$('accountBtn').onclick=()=>{updateAccountPanel(currentLicence?.checkedAt);$('accountDialog').showModal()};$('checkLicence').onclick=async()=>{await checkLicence();if(!$('accountDialog').hidden)$('accountDialog').close()};$('signOutBtn').onclick=signOutCommercial;setAuthMode('signin');const {data:{session}}=await supabaseClient.auth.getSession();currentAuthUser=session?.user||null;if(currentAuthUser)await checkLicence(false);else showAuth();supabaseClient.auth.onAuthStateChange(async(event,sessionNow)=>{if(event==='SIGNED_OUT'){currentAuthUser=null;currentLicence=null;showAuth()}else if(sessionNow?.user&&sessionNow.user.id!==currentAuthUser?.id){currentAuthUser=sessionNow.user;await checkLicence(false)}})}
